result:
	/deep/.el-cascader{
		width: 100%;
	}
	/deep/.el-cascader__search-input{
		margin-left: 8px;
	}
	/deep/.ivu-radio-wrapper{
		margin-right: 25px;
	}
	.box{
		width 64px
		height 64px
		position relative
		border-radius: 3px;
		.pictrue{
			background url(../../assets/images/transparents.jpg) no-repeat
			background-size 100% 100%;
			position: relative;
			width: 100%;
			height: 100%;
			.iconfont{
				position: absolute;
				right:-12px;
				top:-19px;
				font-size: 24px;
				color: #CCCCCC;
			}
		}
		.upload-box{
			display flex
			align-items center
			justify-content center
			width 64px
			height 64px
			border-radius: 3px;
			border: 1px solid #EEEEEE;
			.ivu-icon{
				color: #ccc
			}
		}
		img{
			width 100%;
			height: 100%;
			border-radius: 3px;
		}
	}
	.goods-box{
		.title{
		   color: #999999;
		   font-size: 12px;
		   width: 67px;
		   margin-top: 23px;
		}
		.list{
			width: 236px;
		}
		.list-group{
			display flex
			flex-wrap wrap
		}
		.add-item{
			display flex
			align-items center
			justify-content center
			margin-bottom 10px
			.iconfont-diy{
				font-size 25px
				color #D8D8D8
			}
		}
		.items{
			position relative
			width 64px
			height 64px
			margin-bottom 16px
			margin-right 12px
			border: 1px solid #eee;
			border-radius: 3px;
			img{
				width 100%
				height 100%
			}
			.icondel_1{
				position absolute
				right -10px
				top -16px
				color #CCCCCC
				font-size 22px
				cursor pointer
			}
		}
	}
	.ivu-input-number{
	  width 100%
	}
	.labelInput{
	  border: 1px solid #dcdee2;
	  width 100%;
	  padding 0 8px;
	  border-radius 5px;
	  min-height 30px;
	  background-color: #fff;
	  cursor pointer;
	  .span{
	    color: #C7C7C7;
		font-size: 12px;
	  }
	  .iconxiayi{
	    font-size 12px
	  }
	}
	.conter{
		width: 335px;
		background: #F9F9F9;
		padding: 20px 15px 4px 15px;
		margin-top: 20px;
	}
	.txt_tab{
		margin-top 20px
	}
	.c_row-item{
		margin-bottom 20px
		.slider-box{
			padding-left: 3px;
			&.on{
				padding-left: 10px;
			}
		}
		.label{
			color: #999999;
			font-size: 12px;
		}
		.c_label{
			color: #999999;
			font-size: 12px
		}
		.color-box{
			width: 243px;
		}
	}
	.row-item{
		display flex
		justify-content space-between
		align-items center
	}
	.iconfont{
		font-size 18px
	}
    /deep/.ivu-input{
		font-size 12px!important
	}
    .c_product{
		margin-bottom 20px
		padding: 0 15px
		.list-box{
			.item{
				position relative
				margin-top 20px
				padding 20px 15px 20px 0
				border: 1px solid rgba(238, 238, 238, 1);
				border-radius: 3px;
				// box-shadow: 0 0 10px #eee;

				.delete{
					position absolute
					right 0
					top 0
					right: -13px;
					top: -14px;
					color #ccc
					cursor pointer
				}
			}

			.move-icon{
				display flex
				align-items center
				justify-content center
				width 40px
				cursor move
				.iconxingzhuangjiehe {
					color: #ddd;
				}
			}

			.content{
				flex 1

				.con-item{
					display flex
					align-items center
					margin-bottom 15px

					&:last-child{
						margin-bottom 0
					}
					span{
						width 45px
						font-size 12px
						color: #999
					}
				}
			}
		}

		.add-btn{
			margin-top 18px
		}
	}
    .title{
		font-size 12px
		color #BBBBBB
	}
    .icondrag2{
		color #DDDDDD
		font-size 38px
	}
